import json

with open('threat_bundle.json') as f:
    bundle = json.load(f)

objects_by_id = {obj['id']: obj for obj in bundle['objects']}

for obj in bundle['objects']:
    if obj['type'] == 'relationship' and obj['relationship_type'] == 'indicates':
        source = objects_by_id.get(obj['source_ref'])
        target = objects_by_id.get(obj['target_ref'])
        if source and target:
            print(f"{source.get('name', source['id'])} indicates {target.get('name', target['id'])}")

SEVERITY_MAP = {
    'securityhub': lambda s: 'high' if s >= 7 else 'medium' if s >= 4 else 'low',
    'guardduty':   lambda s: 'high' if s >= 7 else 'medium' if s >= 4 else 'low',
    'sentinel':    lambda s: s.lower(),
}

def normalize(raw, cloud):
    return {
        'cloud': cloud,
        'raw_id': raw['id'],
        'timestamp': to_utc(raw['timestamp']),
        'source_ip': extract_ip(raw),
        'resource': raw.get('resource_id') or raw.get('resource_arn'),
        'severity': SEVERITY_MAP[cloud](raw['severity']),
        'finding_type': raw.get('type') or raw.get('category'),
    }

def correlate(findings, window_minutes=15):
    groups = defaultdict(list)
    for f in findings:
        if f['source_ip']:
            groups[f['source_ip']].append(f)
    cases = []
    for ip, group in groups.items():
        group.sort(key=lambda f: f['timestamp'])
        cluster = []
        for f in group:
            if cluster and (f['timestamp'] - cluster[-1]['timestamp']).seconds > window_minutes * 60:
                cases.append({'confidence': score(cluster), 'findings': cluster})
                cluster = []
            cluster.append(f)
        if cluster:
            cases.append({'confidence': score(cluster), 'findings': cluster})
    return cases

def enrich_alert(alert, intel_client, ticket_store):
    try:
        intel = retry_with_backoff(
            lambda: intel_client.lookup(alert['source_ip']),
            retryable_errors=(TimeoutError, RateLimitError),
            max_attempts=3,
        )
        payload = {'source_ip_intel': intel, 'enrichment_status': 'complete'}
    except (TimeoutError, RateLimitError):
        payload = {'enrichment_status': 'incomplete', 'reason': 'intel API unavailable after retries'}
    except AuthError:
        payload = {'enrichment_status': 'incomplete', 'reason': 'intel API auth failure -- check credentials'}

    # upsert, keyed by alert id -- a replay overwrites, never appends
    ticket_store.upsert(alert_id=alert['id'], field='enrichment', value=payload)
